ROUTE_BLOCK = '\n\n# ════════════════════════════════════════════════════════════════════════════\n# ── VET_PANEL_V2_20260921 ── /api/vet/state — ONE composed payload for the\n# dashboard panel (ORB_PANEL_V2 pattern). Additive: /trades and /status above\n# are untouched. Read-only, never throws, never touches manager state.\n#\n# Why v1 showed "nothing": the panel only knew symbol + entry price. This adds\n# the mark (so MTM exists even when no other engine happens to publish the\n# symbol to LTPStore — VET\'s tick engine keeps its own chain store and does\n# not feed LTPStore), quantity, entry time, expiry, wing marks, today\'s closed\n# groups, and a DB FALLBACK for the position: a carried positional row must be\n# visible while the loop is still booting / waiting for the Zerodha session,\n# and the panel must say loudly that nobody is managing it yet.\n#\n# Masking: the regime/condition block is the signal itself — stripped\n# server-side for non-admin licenses (Phase 2b convention, fails closed).\n# ════════════════════════════════════════════════════════════════════════════\nimport time as _time\n\n_IST_OFF = 5 * 3600 + 30 * 60\n_LTP_FRESH_S = 90          # seconds (wall clock, same unit as LTPStore stamps)\n\n\ndef _ist_day_start(now: int) -> int:\n    """Epoch of 00:00 IST for the IST day containing `now` (real clock)."""\n    return ((int(now) + _IST_OFF) // 86400) * 86400 - _IST_OFF\n\n\ndef _is_admin() -> bool:\n    try:\n        from app.license import license_state\n        return license_state.ui_level() == "admin"\n    except Exception:\n        return False                                   # fail closed\n\n\ndef _mark_for(sym, quote_fn):\n    """(price, source). LTP = a FRESH LTPStore print (someone is publishing\n    the symbol — the panel may tick on it); QUOTE_1M = VET\'s own chain store,\n    last 1m close; LTP_STALE = an old LTPStore print, last resort. A stale\n    print must never outrank VET\'s own quote: LTPStore keeps whatever another\n    engine wrote hours ago. Never logs, never raises."""\n    if not sym:\n        return None, None\n    stale = None\n    try:\n        from app.marketdata.ltp_store import LTPStore\n        got = LTPStore.get_with_timestamp(sym)\n        if got and got[0] and float(got[0]) > 0:\n            if _time.time() - float(got[1] or 0) <= _LTP_FRESH_S:\n                return float(got[0]), "LTP"\n            stale = float(got[0])\n    except Exception:\n        pass\n    if quote_fn is not None:\n        try:\n            q = quote_fn(sym)\n            if q is not None and float(q) > 0:\n                return float(q), "QUOTE_1M"\n        except Exception:\n            pass\n    if stale is not None:\n        return stale, "LTP_STALE"\n    return None, None\n\n\ndef _leg_view(leg, quote_fn):\n    if not leg:\n        return None\n    mark, src = _mark_for(leg.get("tradingsymbol"), quote_fn)\n    return {\n        "symbol": leg.get("tradingsymbol"),\n        "direction": leg.get("direction"),\n        "side": leg.get("instrument_type"),\n        "strike": leg.get("strike"),\n        "expiry": (str(leg.get("expiry"))[:10] if leg.get("expiry") else None),\n        "entry": leg.get("entry_price"),\n        "entry_ts": leg.get("entry_ts"),\n        "qty": leg.get("qty"),\n        "lots": leg.get("lots"),\n        "lot_size": leg.get("lot_size"),\n        "mark": mark, "mark_src": src,\n    }\n\n\ndef _closed_groups(rows, day0):\n    """Closed legs -> one entry per position (wing folded into net)."""\n    groups = {}\n    for r in rows:\n        if r.get("status") != "CLOSED" or not r.get("exit_ts"):\n            continue\n        groups.setdefault(r["group_id"], []).append(r)\n    out = []\n    for gid, legs in groups.items():\n        main = next((l for l in legs if l.get("leg_role") == "MAIN"), legs[0])\n\n        def _n(l):\n            v = l.get("net_pnl")\n            return float(v if v is not None else (l.get("pnl") or 0))\n        out.append({\n            "group_id": gid,\n            "symbol": main.get("tradingsymbol"),\n            "direction": main.get("direction"),\n            "side": main.get("instrument_type"),\n            "qty": main.get("qty"), "lots": main.get("lots"),\n            "entry": main.get("entry_price"), "exit": main.get("exit_price"),\n            "entry_ts": main.get("entry_ts"), "exit_ts": main.get("exit_ts"),\n            "reason": main.get("exit_reason"),\n            "gross": round(sum(float(l.get("pnl") or 0) for l in legs), 2),\n            "charges": round(sum(float(l.get("charges") or 0) for l in legs), 2),\n            "net": round(sum(_n(l) for l in legs), 2),\n            "has_wing": any(l.get("leg_role") == "WING" for l in legs),\n            "today": int(main.get("exit_ts") or 0) >= day0,\n        })\n    out.sort(key=lambda g: g["exit_ts"] or 0, reverse=True)\n    return out\n\n\n@router.get("/state")\ndef vet_state():\n    now = int(_time.time())\n    day0 = _ist_day_start(now)\n    out = {"ok": True, "strategy": "VET_V1", "running": False, "mode": None,\n           "leg_action": None, "positional": None, "hedged": False,\n           "frozen": False, "freeze_reason": None, "engine": None,\n           "signal": None, "spot": None, "cfg": {}, "day": {},\n           "position": None, "position_source": None,\n           "closed": [], "today_net": 0.0, "server_ts": now}\n    admin = _is_admin()\n    m = e = None\n    try:\n        from app.engine.vet.vet_selection_loop import get_engine, get_manager\n        m, e = get_manager(), get_engine()\n    except Exception as exc:\n        out["error"] = repr(exc)\n\n    # ── config: from the running manager, else from disk (loop not up) ──\n    cfg = {}\n    try:\n        if m is not None:\n            cfg = dict(m.cfg or {})\n        else:\n            from app.config.strategy_loader import load_strategy_config\n            cfg = dict(load_strategy_config("VET_V1") or {})\n    except Exception:\n        cfg = {}\n    q = cfg.get("quantity") or {}\n    eod_square = bool(cfg.get("eod_square", True))\n    out["mode"] = (m.mode if m is not None\n                   else str(cfg.get("trade_execution_mode") or "").upper() or None)\n    out["leg_action"] = str(cfg.get("leg_action") or "BUY").upper()\n    out["positional"] = not eod_square\n    out["cfg"] = {\n        "lots": q.get("lots"), "lot_size": q.get("lot_size"),\n        "entry_cutoff": cfg.get("entry_cutoff", "15:00"),\n        "exit_time": cfg.get("exit_time", "15:15"),\n        "max_trades_per_day": int(cfg.get("max_trades_per_day") or 0),\n        "hedge_enabled": bool(cfg.get("hedge_enabled")),\n        "hedge_max_premium": cfg.get("hedge_max_premium"),\n    }\n\n    quote_fn = None\n    if m is not None:\n        out["running"] = True\n        quote_fn = getattr(m, "quote_fn", None)\n        try:\n            out["hedged"] = bool(m.wants_wing)\n            out["frozen"] = bool(m.frozen)\n            out["freeze_reason"] = m.freeze_reason\n            out["day"] = {"entries": int(getattr(m, "_day_entries", 0) or 0)}\n            sp = (m.cfg or {}).get("_spot")\n            if sp:\n                out["spot"] = {"ltp": float(sp), "src": "1M_CLOSE"}\n        except Exception:\n            pass\n\n    if e is not None:\n        try:\n            es = e.status()\n            out["engine"] = {k: es.get(k) for k in (\n                "warmup_sessions", "warmup_required", "warmup_ok",\n                "bars_today", "last_bar_ts")}\n            if es.get("frozen"):\n                out["frozen"] = True\n                out["freeze_reason"] = es.get("freeze_reason") or out["freeze_reason"]\n            sig = e.latest_signal()\n            if sig and admin:                          # the signal IS the recipe\n                out["signal"] = {k: sig.get(k) for k in (\n                    "bar_ts", "condition", "in_range", "dir_trend", "spot")}\n        except Exception:\n            pass\n\n    # ── position: manager truth first, DB truth when the loop is not up ──\n    main = wing = None\n    gid = None\n    try:\n        if m is not None and m.pos is not None:\n            gid, main, wing = m.pos.get("group_id"), m.pos.get("main"), m.pos.get("wing")\n            out["position_source"] = "MANAGER"\n        elif m is None:\n            g = _repo().open_group(None)\n            if g and g.get("main"):\n                gid, main, wing = g["group_id"], g["main"], g.get("wing")\n                out["position_source"] = "DB"\n    except Exception as exc:\n        out["error"] = repr(exc)\n    if main:\n        pv = _leg_view(main, quote_fn)\n        pv["group_id"] = gid\n        pv["mode"] = main.get("mode")\n        pv["carried"] = int(main.get("entry_ts") or now) < day0\n        pv["signal_bar_ts"] = main.get("signal_bar_ts")\n        if admin:\n            pv["condition"] = main.get("condition")\n        pv["wing"] = _leg_view(wing, quote_fn)\n        out["position"] = pv\n\n    # ── closed positions: today\'s + the recent tail (positional strategy —\n    # "today" is often empty, the last few exits are the useful context) ──\n    try:\n        import sqlite3\n        repo = _repo()\n        with sqlite3.connect(repo.db_path, timeout=30) as c:\n            c.row_factory = sqlite3.Row\n            rows = [dict(r) for r in c.execute(\n                "SELECT * FROM vet_trades WHERE status=\'CLOSED\' "\n                "ORDER BY exit_ts DESC LIMIT 40")]\n        groups = _closed_groups(rows, day0)\n        if not admin:\n            for g in groups:\n                g["reason"] = "CLOSED"\n        out["closed"] = groups[:12]\n        out["today_net"] = round(sum(g["net"] for g in groups if g["today"]), 2)\n        out["day"]["closed_today"] = sum(1 for g in groups if g["today"])\n    except Exception:\n        pass\n    return out\n# ── VET_PANEL_V2_20260921 END ──\n'

PANEL_BODY = '// frontend/src/strategies/vet/VETPanel.jsx\n//\n// ── VET_V1 dashboard panel · v2 ── Fence: VET_PANEL_V2_20260921\n// v1 rendered "SHORT <symbol> @ <entry>" and nothing else, and its cards read\n// tokens that do not exist (colors.bgAlt, colors.border as a string) so they\n// had no surface at all. v2 is ORB/TMA2-panel parity where VET has the\n// concept:\n//   * POSITION CARD — direction/side chips, qty, held-since (carried days),\n//     ticking LTP + MTM, points, premium-captured track (SHORT) or points\n//     track (LONG), wing line + combined P&L, expiry and the auto-exit time.\n//   * SCOREBOARD — open MTM, today\'s closed net, day total, spot, entries\n//     vs cap, last 5m bar (the engine heartbeat: VET decides on 5m closes).\n//   * Banners — FROZEN, WARMUP SHORT, and the one v1 could not show at all:\n//     an OPEN ROW IN THE DB WHILE THE LOOP IS NOT UP (unmanaged position).\n//   * Closed table — today\'s exits plus the recent tail (positional: "today"\n//     is usually empty, the last few exits are the context).\n// Structure from /api/vet/state (4 s poll). The mark ticks from ltpMap ONLY\n// when the route says a fresh publisher exists (mark_src === "LTP"); VET\'s\n// own tick engine does not feed LTPStore, so otherwise the route\'s 1m-close\n// quote is the honest number and the card says so.\n// UI_MASK: regime/condition and exit reasons are admin-only (the route\n// strips them server-side too; this is the curtain).\n// No square-off button by design — VET\'s only manual path is the kill\n// switch (flatten + freeze); a bare manual close would be re-entered by the\n// next 5m decision.\n\nimport { useEffect, useState } from "react";\nimport { getApiBase } from "../../api/base";\nimport { colors, spacing, typography, pnlStyle, alpha } from "../../tokens";\nimport { useEntitlements } from "../../hooks/useEntitlements";   // ── UI_MASK ──\nimport { stratName } from "../displayNames";                      // ── UI_MASK ──\n\nconst ACCENT = "#34d399";\nconst IST = { timeZone: "Asia/Kolkata" };\n\nfunction normalizeSymbol(sym) { return sym ? sym.replace(/\\s+/g, "").toUpperCase() : sym; }\nfunction fmtInr(v) {\n  if (v == null || isNaN(v)) return "—";\n  const a = Math.abs(Math.round(v));\n  return `${v < 0 ? "−" : v > 0 ? "+" : ""}₹${a.toLocaleString("en-IN")}`;\n}\nfunction fmt2(v) { return v == null || isNaN(v) ? "—" : Number(v).toFixed(2); }\nfunction fmtPts(v) { return v == null || isNaN(v) ? "—" : `${v >= 0 ? "+" : "−"}${Math.abs(v).toFixed(2)}`; }\nfunction dayKey(d) { return d.toLocaleDateString("en-CA", IST); }           // YYYY-MM-DD in IST\nfunction hhmm(ts) {\n  if (!ts) return "—";\n  return new Date(ts * 1000).toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit", hour12: false, ...IST });\n}\n// Positional: a bare "10:21" is ambiguous across days — other-day stamps carry the date.\nfunction fmtTs(ts) {\n  if (!ts) return "—";\n  const d = new Date(ts * 1000);\n  if (dayKey(d) === dayKey(new Date())) return hhmm(ts);\n  return `${d.toLocaleDateString("en-IN", { day: "2-digit", month: "short", ...IST })} · ${hhmm(ts)}`;\n}\nfunction heldFor(ts) {\n  if (!ts) return null;\n  const s = Math.max(0, Math.floor(Date.now() / 1000 - ts));\n  const d = Math.floor(s / 86400), h = Math.floor((s % 86400) / 3600), m = Math.floor((s % 3600) / 60);\n  return d > 0 ? `${d}d ${h}h` : h > 0 ? `${h}h ${m}m` : `${m}m`;\n}\n// Calendar days to expiry, both ends in IST. 0 = expires today.\nfunction daysToExpiry(iso) {\n  if (!iso) return null;\n  const a = Date.parse(`${dayKey(new Date())}T00:00:00Z`), b = Date.parse(`${String(iso).slice(0, 10)}T00:00:00Z`);\n  return isNaN(a) || isNaN(b) ? null : Math.round((b - a) / 86400000);\n}\nfunction expiryLabel(iso) {\n  if (!iso) return "—";\n  const d = new Date(`${String(iso).slice(0, 10)}T00:00:00+05:30`);\n  return d.toLocaleDateString("en-IN", { weekday: "short", day: "2-digit", month: "short", ...IST });\n}\nfunction minHHMM(a, b) { return String(a) <= String(b) ? a : b; }\n\nconst clamp01 = (x) => Math.max(0, Math.min(1, x));\n\nexport default function VETPanel({ strategyId = "VET_V1", ltpMap = {} }) {\n  const [st, setSt] = useState(null);\n  const [down, setDown] = useState(false);\n  const { loaded: licenseLoaded, isAdminUi } = useEntitlements();\n  const showParams = !licenseLoaded || isAdminUi;                 // fail-OPEN curtain\n\n  useEffect(() => {\n    let alive = true;\n    const pull = async () => {\n      try {\n        const r = await fetch(`${getApiBase()}/api/vet/state`);\n        if (!r.ok) throw new Error(String(r.status));\n        const d = await r.json();\n        if (alive) { setSt(d); setDown(false); }\n      } catch { if (alive) setDown(true); /* keep last payload */ }\n    };\n    pull();\n    const t = setInterval(pull, 4000);\n    return () => { alive = false; clearInterval(t); };\n  }, []);\n\n  const pos = st?.position || null;\n  const wing = pos?.wing || null;\n  const cfg = st?.cfg || {};\n  const eng = st?.engine;\n  const sig = st?.signal;\n  const closed = st?.closed || [];\n  const isShort = pos?.direction === "SHORT";\n\n  // ── marks: tick from ltpMap only when the route vouches for a fresh publisher ──\n  const markOf = (leg) => {\n    if (!leg) return { px: null, live: false };\n    if (leg.mark_src === "LTP") {\n      const v = ltpMap?.[normalizeSymbol(leg.symbol)];\n      if (typeof v === "number" && v > 0) return { px: v, live: true };\n    }\n    return { px: leg.mark ?? null, live: false };\n  };\n  const mk = markOf(pos), wmk = markOf(wing);\n  const pts = pos && mk.px != null ? (isShort ? pos.entry - mk.px : mk.px - pos.entry) : null;\n  const mainMtm = pts != null ? pts * (pos.qty || 0) : null;\n  const wingMtm = wing && wmk.px != null ? (wmk.px - wing.entry) * (wing.qty || 0) : null;\n  const openMtm = mainMtm != null ? mainMtm + (wingMtm || 0) : null;\n  const todayNet = st?.today_net ?? 0;\n  const dayTotal = todayNet + (openMtm ?? 0);\n  const pctOfPremium = pts != null && pos.entry > 0 ? (pts / pos.entry) * 100 : null;\n\n  const spotLive = ltpMap?.NIFTY50;\n  const spot = typeof spotLive === "number" && spotLive > 0 ? spotLive : st?.spot?.ltp ?? sig?.spot ?? null;\n\n  const dte = daysToExpiry(pos?.expiry);\n  const expiryExit = minHHMM(cfg.exit_time || "15:15", "15:20");\n  const cap = cfg.max_trades_per_day || 0;\n  const entries = st?.day?.entries ?? 0;\n  const warmShort = eng && eng.warmup_ok === false;\n  const unmanaged = pos && st?.position_source === "DB";\n  const barAge = eng?.last_bar_ts ? Date.now() / 1000 - (eng.last_bar_ts + 300) : null;   // since that bar CLOSED\n  const barStale = st?.running && barAge != null && barAge > 480 && barAge < 6 * 3600;\n\n  const phase = !st ? ["OFFLINE", "muted"]\n    : st.frozen ? ["FROZEN", "bad"]\n    : unmanaged ? ["POSITION UNMANAGED", "bad"]\n    : !st.running ? ["LOOP NOT UP", "muted"]\n    : warmShort ? ["WARMUP SHORT", "bad"]\n    : pos ? ["IN POSITION", "accent"]\n    : cap > 0 && entries >= cap ? ["DAY CAP REACHED", "muted"]\n    : ["FLAT · ARMED", "good"];\n\n  // ── styles (tokens only — every surface follows the theme) ──\n  const card = { background: colors.bg.secondary, borderRadius: 10, padding: spacing.lg,\n                 marginBottom: spacing.md, border: `1px solid ${colors.border.light}` };\n  const label = { ...typography.label, fontSize: 10.5, color: colors.text.muted };\n  const num = { ...typography.mono };\n  const tone = { good: colors.profit, bad: colors.loss, accent: ACCENT, muted: colors.text.muted, info: colors.primary };\n  const chip = (text, t = "muted") => (\n    <span style={{ background: alpha(tone[t], 16), color: tone[t], border: `1px solid ${alpha(tone[t], 35)}`,\n                   borderRadius: 6, padding: "2px 8px", fontSize: 11, fontWeight: 700, whiteSpace: "nowrap", letterSpacing: 0.3 }}>{text}</span>\n  );\n  const Stat = ({ k, v, sub, style, big }) => (\n    <div style={{ minWidth: 104 }}>\n      <div style={label}>{k}</div>\n      <div style={{ fontSize: big ? 22 : 16, fontWeight: 700, lineHeight: 1.25, ...num, ...style }}>{v}</div>\n      {sub && <div style={{ fontSize: 10.5, color: colors.text.muted, marginTop: 1 }}>{sub}</div>}\n    </div>\n  );\n  const banner = (title, body) => (\n    <div style={{ ...card, borderColor: alpha(colors.loss, 60), background: alpha(colors.loss, 12), fontSize: 12 }}>\n      <b style={{ color: colors.loss }}>{title}</b> <span style={{ color: colors.text.secondary }}>— {body}</span>\n    </div>\n  );\n\n  const regimeText = sig\n    ? (sig.in_range ? "IN CHANNEL" : sig.condition > 0 ? "BULL" : sig.condition < 0 ? "BEAR" : "NEUTRAL")\n    : null;\n\n  // premium track. SHORT: entry → 0, fill = premium captured; overshoot above entry fills red.\n  // LONG: no natural bound — fill to ±100% of entry premium around a centre line.\n  const track = (() => {\n    if (!pos || mk.px == null || !(pos.entry > 0)) return null;\n    const f = clamp01(Math.abs(pts) / pos.entry);\n    return { frac: f, win: pts >= 0 };\n  })();\n\n  return (\n    <div style={{ padding: spacing.md, color: colors.text.primary }}>\n      {/* ── header ── */}\n      <div style={{ display: "flex", alignItems: "center", gap: spacing.md, flexWrap: "wrap", marginBottom: spacing.md }}>\n        <div>\n          <div style={{ fontSize: 16, fontWeight: 800 }}>\n            {stratName(strategyId, showParams)}\n            <span style={{ marginLeft: 8, fontSize: 11, color: colors.text.muted, fontWeight: 500 }}>\n              {showParams ? "Velvet · dual-EMA regime channel · 5m NIFTY spot" : "NIFTY 5m trend"}\n            </span>\n          </div>\n          <div style={{ fontSize: 11, color: colors.text.muted, marginTop: 2 }}>\n            {st ? `${st.leg_action === "SELL" ? "option selling" : "option buying"} · one position at a time · ${st.positional ? "positional (carries overnight)" : `intraday, flat by ${cfg.exit_time || "15:15"}`}${st.hedged ? " · wing-hedged" : ""} · no SL/TP by design — exits on signal` : "loading…"}\n          </div>\n        </div>\n        <span style={{ marginLeft: "auto", display: "flex", gap: 6, alignItems: "center", flexWrap: "wrap" }}>\n          {chip(phase[0], phase[1])}\n          {st?.mode && chip(st.mode, st.mode === "LIVE" ? "bad" : "info")}\n          {st?.running && chip(eng?.last_bar_ts ? `${barStale ? "NO 5m BAR SINCE" : "5m bar"} ${hhmm(eng.last_bar_ts)}` : "awaiting first 5m bar", barStale ? "bad" : "muted")}\n          {down && chip("BACKEND UNREACHABLE", "bad")}\n        </span>\n      </div>\n\n      {/* ── banners: silent failure is the enemy ── */}\n      {st?.frozen && banner("ENGINE FROZEN", st.freeze_reason || "prefix guard tripped — no new entries (fail closed). An open position still exits.")}\n      {!st?.frozen && warmShort && banner("WARMUP SHORT", `${eng.warmup_sessions}/${eng.warmup_required} sessions — decisions are blocked until warm.`)}\n      {unmanaged && banner("OPEN POSITION IS NOT BEING MANAGED", "this row is read from the database; the VET loop is not up (waiting for the Zerodha session or warmup, mode OFF, or still booting). No exit will fire until it starts.")}\n      {st && !st.running && !unmanaged && (\n        <div style={{ ...card, fontSize: 12, color: colors.text.muted }}>\n          Loop not up — waiting for the Zerodha session / warmup, mode OFF, not licensed, or the backend is still booting (40–45 s).\n        </div>\n      )}\n\n      {/* ── scoreboard ── */}\n      <div style={{ ...card, display: "flex", gap: spacing.xl, flexWrap: "wrap", alignItems: "flex-start" }}>\n        <Stat big k="Open MTM" v={openMtm != null ? fmtInr(openMtm) : pos ? "…" : "—"} style={openMtm != null ? pnlStyle(openMtm) : { color: colors.text.muted }}\n              sub={pos ? (mk.live ? "ticking · before charges" : mk.px != null ? "last 1m close · before charges" : "no price yet") : "flat"} />\n        <Stat k="Closed today" v={fmtInr(todayNet)} style={pnlStyle(todayNet)} sub={`${st?.day?.closed_today ?? 0} position${(st?.day?.closed_today ?? 0) === 1 ? "" : "s"} · net of charges`} />\n        <Stat k="Day total" v={fmtInr(dayTotal)} style={pnlStyle(dayTotal)} sub="closed net + open MTM" />\n        <Stat k="NIFTY spot" v={spot != null ? Number(spot).toLocaleString("en-IN", { maximumFractionDigits: 1 }) : "…"} sub={eng ? `${eng.bars_today ?? 0} 1m bars today` : "engine not up"} />\n        <Stat k="Entries today" v={cap > 0 ? `${entries} / ${cap}` : `${entries}`} sub={cap > 0 ? "daily cap" : "no daily cap"} />\n        {showParams && regimeText && (\n          <Stat k="Regime · last 5m" v={regimeText} style={{ color: sig.in_range ? colors.text.secondary : sig.condition > 0 ? colors.profit : sig.condition < 0 ? colors.loss : colors.text.secondary }}\n                sub={`trend ${sig.dir_trend > 0 ? "up" : sig.dir_trend < 0 ? "down" : "flat"} · bar ${hhmm(sig.bar_ts)}`} />\n        )}\n      </div>\n\n      {/* ── open position ── */}\n      <div style={{ ...card, borderLeft: `3px solid ${pos ? ACCENT : colors.border.light}` }}>\n        <div style={{ ...label, marginBottom: 10 }}>Open position · decisions at 5-minute closes only</div>\n        {!pos && (\n          <div style={{ fontSize: 12, color: colors.text.muted }}>\n            Flat{eng?.last_bar_ts ? ` · last 5m bar ${fmtTs(eng.last_bar_ts)}` : ""} · no new entries after {cfg.entry_cutoff || "15:00"}.\n          </div>\n        )}\n        {pos && (\n          <>\n            <div style={{ display: "flex", gap: spacing.md, flexWrap: "wrap", alignItems: "center", marginBottom: 12 }}>\n              {chip(pos.direction, isShort ? "bad" : "good")}\n              {chip(pos.side, pos.side === "CE" ? "good" : "bad")}\n              <b style={{ fontSize: 15, ...num }}>{pos.symbol}</b>\n              <span style={{ fontSize: 12, color: colors.text.muted }}>\n                {pos.mode} · {pos.lots ?? "—"} lot{pos.lots === 1 ? "" : "s"} · qty {pos.qty}\n              </span>\n              {pos.carried && chip("CARRIED", "info")}\n              <span style={{ marginLeft: "auto", textAlign: "right", ...num }}>\n                <span style={{ fontSize: 11, color: colors.text.muted }}>LTP </span>\n                <b style={{ fontSize: 20 }}>{mk.px != null ? fmt2(mk.px) : "…"}</b>\n                {mainMtm != null && <b style={{ ...pnlStyle(mainMtm), fontSize: 20, marginLeft: 14 }}>{fmtInr(mainMtm)}</b>}\n              </span>\n            </div>\n\n            {/* premium track */}\n            <div style={{ display: "flex", justifyContent: "space-between", fontSize: 10.5, color: colors.text.muted, marginBottom: 4, ...num }}>\n              <span>{isShort ? `sold @ ${fmt2(pos.entry)} — falling premium is profit` : `bought @ ${fmt2(pos.entry)} — rising premium is profit`}</span>\n              <span>{isShort ? "premium → 0 (max profit)" : "+100% of premium"}</span>\n            </div>\n            <div style={{ position: "relative", height: 8, background: colors.bg.tertiary, borderRadius: 4, overflow: "hidden" }}>\n              {track && <div style={{ position: "absolute", left: 0, top: 0, bottom: 0, width: `${track.frac * 100}%`, borderRadius: 4,\n                                      background: track.win ? colors.profit : colors.loss, transition: "width 0.5s ease" }} />}\n            </div>\n            <div style={{ fontSize: 10.5, color: colors.text.tertiary, marginTop: 4, ...num }}>\n              {track\n                ? (track.win\n                    ? `${Math.abs(pctOfPremium).toFixed(0)}% of the ${isShort ? "sold" : "paid"} premium ${isShort ? "captured" : "gained"}`\n                    : `${Math.abs(pctOfPremium).toFixed(0)}% of entry premium AGAINST the position — no stop by design; the exit is the signal`)\n                : "price unavailable — levels only"}\n            </div>\n\n            {/* facts grid */}\n            <div style={{ display: "flex", gap: spacing.xl, flexWrap: "wrap", marginTop: 14, paddingTop: 12, borderTop: `1px solid ${colors.border.dark}` }}>\n              <Stat k="Entry" v={fmt2(pos.entry)} sub={fmtTs(pos.entry_ts)} />\n              <Stat k="Points" v={fmtPts(pts)} style={pts != null ? pnlStyle(pts) : undefined} sub={pctOfPremium != null ? `${pctOfPremium >= 0 ? "+" : "−"}${Math.abs(pctOfPremium).toFixed(1)}% of premium` : "—"} />\n              <Stat k="Held" v={heldFor(pos.entry_ts) ?? "—"} sub={pos.carried ? "carried from a prior session" : "opened today"} />\n              <Stat k="Strike" v={pos.strike != null ? Number(pos.strike).toLocaleString("en-IN") : "—"}\n                    sub={spot != null && pos.strike != null ? `${Math.abs(spot - pos.strike).toFixed(0)} pts ${((pos.side === "PE") === (spot > pos.strike)) ? "OTM" : "ITM"}` : pos.side} />\n              <Stat k="Expiry" v={expiryLabel(pos.expiry)}\n                    style={dte != null && dte <= 0 ? { color: colors.warning } : undefined}\n                    sub={dte == null ? "—" : dte <= 0 ? `TODAY · auto-exit ${expiryExit}` : dte === 1 ? `tomorrow · auto-exit ${expiryExit}` : `in ${dte} days · auto-exit ${expiryExit} that day`} />\n              {isShort && mk.px != null && <Stat k="Left on table" v={fmtInr(mk.px * (pos.qty || 0)).replace("+", "")} sub="if premium decays to 0" />}\n            </div>\n\n            {/* wing */}\n            {wing && (\n              <div style={{ display: "flex", gap: spacing.lg, flexWrap: "wrap", alignItems: "center", fontSize: 12, marginTop: 12, paddingTop: 10, borderTop: `1px solid ${colors.border.dark}`, ...num }}>\n                {chip("WING · LONG", "info")}\n                <b>{wing.symbol}</b>\n                <span style={{ color: colors.text.muted }}>@ {fmt2(wing.entry)} · LTP {wmk.px != null ? fmt2(wmk.px) : "…"}</span>\n                {wingMtm != null && <b style={pnlStyle(wingMtm)}>{fmtInr(wingMtm)}</b>}\n                <span style={{ marginLeft: "auto" }}>\n                  <span style={{ color: colors.text.muted }}>spread </span>\n                  <b style={openMtm != null ? pnlStyle(openMtm) : undefined}>{fmtInr(openMtm)}</b>\n                </span>\n              </div>\n            )}\n\n            <div style={{ fontSize: 11, color: colors.text.muted, marginTop: 12 }}>\n              exits: {showParams ? "FLIP · SIGNAL EXIT" : "signal"} · {st?.positional ? `expiry day ${expiryExit}` : `EOD ${cfg.exit_time || "15:15"}`} · kill switch\n              {pos.mode === "LIVE" ? " · engine exits, no GTT at the broker" : ""}\n              {!mk.live && mk.px != null ? " · price is the last 1-minute close (this contract is not on the shared tick feed)" : ""}\n            </div>\n          </>\n        )}\n      </div>\n\n      {/* ── closed positions ── */}\n      <div style={card}>\n        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 8 }}>\n          <div style={label}>Closed positions · today and recent</div>\n          <div style={{ fontSize: 12, ...num }}>\n            <span style={{ color: colors.text.muted }}>today </span><b style={pnlStyle(todayNet)}>{fmtInr(todayNet)}</b>\n          </div>\n        </div>\n        {closed.length === 0 && <div style={{ fontSize: 12, color: colors.text.muted }}>No closed positions yet.</div>}\n        {closed.length > 0 && (\n          <div style={{ overflowX: "auto" }}>\n            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12, ...num }}>\n              <thead>\n                <tr style={{ color: colors.text.muted, textAlign: "left" }}>\n                  {["Exit", "Dir", "Symbol", "Lots", "Entry", "Exit px", "Reason", "Charges", "Net P&L"].map((h, i) => (\n                    <th key={h} style={{ fontWeight: 600, fontSize: 10.5, letterSpacing: 0.4, textTransform: "uppercase", padding: "4px 6px",\n                                         textAlign: i >= 3 && h !== "Reason" ? "right" : "left", borderBottom: `1px solid ${colors.border.light}` }}>{h}</th>\n                  ))}\n                </tr>\n              </thead>\n              <tbody>\n                {closed.map((g) => (\n                  <tr key={g.group_id} style={{ borderBottom: `1px solid ${colors.border.dark}`, opacity: g.today ? 1 : 0.62 }}>\n                    <td style={{ padding: "5px 6px" }}>{fmtTs(g.exit_ts)}</td>\n                    <td style={{ padding: "5px 6px" }}>{chip(g.direction === "SHORT" ? "S" : "L", g.direction === "SHORT" ? "bad" : "good")}</td>\n                    <td style={{ padding: "5px 6px" }}><b>{g.symbol}</b>{g.has_wing && <span style={{ color: colors.text.muted }}> + wing</span>}</td>\n                    <td style={{ padding: "5px 6px", textAlign: "right" }}>{g.lots ?? "—"}</td>\n                    <td style={{ padding: "5px 6px", textAlign: "right" }}>{fmt2(g.entry)}</td>\n                    <td style={{ padding: "5px 6px", textAlign: "right" }}>{fmt2(g.exit)}</td>\n                    <td style={{ padding: "5px 6px", color: colors.text.secondary }}>{showParams ? (g.reason || "—") : "CLOSED"}</td>\n                    <td style={{ padding: "5px 6px", textAlign: "right", color: colors.text.muted }}>{g.charges ? `₹${Math.round(g.charges).toLocaleString("en-IN")}` : "—"}</td>\n                    <td style={{ padding: "5px 6px", textAlign: "right", fontWeight: 700, ...pnlStyle(g.net) }}>{fmtInr(g.net)}</td>\n                  </tr>\n                ))}\n              </tbody>\n            </table>\n          </div>\n        )}\n      </div>\n\n      <div style={{ fontSize: 10.5, color: colors.text.muted, padding: "0 4px" }}>\n        {cfg.lots ?? "—"} lot{cfg.lots === 1 ? "" : "s"} × {cfg.lot_size ?? "—"} · no new entries ≥ {cfg.entry_cutoff || "15:00"}\n        {cfg.hedge_enabled ? ` · wing ≤ ₹${cfg.hedge_max_premium}` : ""} · today = exit-timestamp based (IST) · open card ignores entry day\n      </div>\n    </div>\n  );\n}\n'

TEST_BODY = '# backend/app/api/test_vet_state_route.py\n#\n# ── VET_PANEL_V2_20260921 ── behavioural suite for GET /api/vet/state.\n# Calls the route function directly (no TestClient — build-Mac httpx pin).\n# Every timestamp is on the REAL epoch clock (TSG_BANK_FIX1 scar): the\n# "today" boundary and the LTP freshness window are compared against\n# time.time(), so toy integers would prove nothing.\n#\n#   cd backend && PYTHONPATH=$PWD python3 app/api/test_vet_state_route.py\n\nimport os\nimport sys\nimport tempfile\nimport time\n\nimport app.api.vet_state_routes as R\nimport app.engine.vet.vet_selection_loop as L\nfrom app.engine.vet.vet_common import VetRepo\nfrom app.license import license_state\nfrom app.marketdata.ltp_store import LTPStore\n\nFAILS = []\n\n\ndef check(name, cond, detail=""):\n    print(f"  {\'PASS\' if cond else \'FAIL\'}  {name}" + (f"  [{detail}]" if detail and not cond else ""))\n    if not cond:\n        FAILS.append(name)\n\n\nNOW = int(time.time())\nDAY0 = R._ist_day_start(NOW)\nSYM, WSYM = "NIFTYTEST23400PE", "NIFTYTEST22900PE"\n\ntmp = tempfile.mkdtemp(prefix="vet_state_")\nrepo = VetRepo(os.path.join(tmp, "app.db"))\nrepo.ensure_schema()\nR._repo = lambda: repo                      # route reads THIS db\n_real_level = license_state.ui_level\n\n\ndef set_admin(on):\n    license_state.ui_level = (lambda: "admin") if on else (lambda: "standard")\n\n\ndef leg(gid, role, sym, direction, entry_ts, px, **kw):\n    row = {"group_id": gid, "leg_role": role, "mode": "PAPER", "direction": direction,\n           "tradingsymbol": sym, "token": 1, "instrument_type": "PE", "strike": 23400.0,\n           "expiry": "2026-09-22", "qty": 650, "lots": 10, "lot_size": 65,\n           "entry_ts": entry_ts, "entry_price": px, "entry_order_id": "P1",\n           "signal_bar_ts": entry_ts - 300, "condition": 1, "leg_action": "SELL"}\n    row.update(kw)\n    row["id"] = repo.insert_leg(row)\n    return row\n\n\nclass FakeMgr:\n    mode = "PAPER"; frozen = False; freeze_reason = None; wants_wing = False\n    _day_entries = 1\n\n    def __init__(self, pos, quote_fn):\n        self.cfg = {"leg_action": "SELL", "eod_square": False, "_spot": 23364.85,\n                    "quantity": {"lots": 10, "lot_size": 65}, "max_trades_per_day": 3}\n        self.pos, self.quote_fn = pos, quote_fn\n\n\nclass FakeEng:\n    def status(self):\n        return {"frozen": False, "freeze_reason": None, "warmup_sessions": 10,\n                "warmup_required": 10, "warmup_ok": True, "bars_today": 80,\n                "last_bar_ts": NOW - NOW % 300 - 300}\n\n    def latest_signal(self):\n        return {"bar_ts": NOW - 600, "condition": 1, "in_range": False,\n                "dir_trend": 1, "spot": 23360.0, "last1m_ts": NOW - 360, "warmup_ok": True}\n\n\ndef clear_ltp():\n    with LTPStore._lock:\n        LTPStore._prices.pop(SYM, None); LTPStore._timestamps.pop(SYM, None)\n\n\nprint("── 1. IST day boundary on the real clock")\ncheck("day start <= now < day start + 24h", DAY0 <= NOW < DAY0 + 86400, f"{DAY0} {NOW}")\ncheck("day start is 00:00 IST", (DAY0 + 5 * 3600 + 1800) % 86400 == 0)\n\nprint("── 2. loop NOT up, carried SHORT row in the DB (this morning\'s screenshot)")\nL._manager = None; L._engine = None\nset_admin(True); clear_ltp()\nmain = leg("g_open", "MAIN", SYM, "SHORT", DAY0 - 3 * 86400 + 36000, 144.6)\ns = R.vet_state()\np = s["position"]\ncheck("payload ok, running False", s["ok"] and s["running"] is False)\ncheck("position surfaced from DB", p is not None and s["position_source"] == "DB")\ncheck("symbol / entry / qty / lots", p and (p["symbol"], p["entry"], p["qty"], p["lots"]) == (SYM, 144.6, 650, 10))\ncheck("carried flag true for a prior-day entry", p and p["carried"] is True)\ncheck("expiry normalised to ISO date", p and p["expiry"] == "2026-09-22")\ncheck("no publisher, no quote_fn -> mark None (never invented)", p and p["mark"] is None and p["mark_src"] is None)\n\nprint("── 3. manager up: mark source ladder")\nmgr = FakeMgr({"group_id": "g_open", "side": "PE", "main": main, "wing": None}, lambda sym: 89.85)\nL._manager, L._engine = mgr, FakeEng()\ns = R.vet_state(); p = s["position"]\ncheck("running True, source MANAGER", s["running"] and s["position_source"] == "MANAGER")\ncheck("QUOTE_1M when LTPStore is empty", p["mark"] == 89.85 and p["mark_src"] == "QUOTE_1M")\nLTPStore.update(SYM, 88.10)\np = R.vet_state()["position"]\ncheck("fresh LTPStore print wins -> LTP", p["mark"] == 88.10 and p["mark_src"] == "LTP")\nwith LTPStore._lock:\n    LTPStore._timestamps[SYM] = time.time() - 3600          # an hour-old print\np = R.vet_state()["position"]\ncheck("STALE LTPStore print never outranks VET\'s own quote", p["mark"] == 89.85 and p["mark_src"] == "QUOTE_1M")\nmgr.quote_fn = lambda sym: None\np = R.vet_state()["position"]\ncheck("stale print is the last resort, labelled", p["mark"] == 88.10 and p["mark_src"] == "LTP_STALE")\nmgr.quote_fn = lambda sym: (_ for _ in ()).throw(RuntimeError("boom"))\ncheck("quote_fn raising never breaks the route", R.vet_state()["ok"] is True)\nmgr.quote_fn = lambda sym: 89.85\nmtm = (p["entry"] - 89.85) * p["qty"]\ncheck("screenshot arithmetic: (144.6-89.85)*650 = 35,587.5", abs(mtm - 35587.5) < 1e-6, str(mtm))\n\nprint("── 4. masking (Phase 2b): the signal is admin-only, fails closed")\ns = R.vet_state()\ncheck("admin sees regime + entry condition", s["signal"] and s["signal"]["condition"] == 1 and s["position"].get("condition") == 1)\nset_admin(False)\ns = R.vet_state()\ncheck("standard: no signal block", s["signal"] is None)\ncheck("standard: no condition on the position", "condition" not in s["position"])\ncheck("standard still gets position + mark", s["position"]["mark"] == 89.85)\n\nprint("── 5. closed groups: exit-timestamp \'today\', wing folded in")\ny = leg("g_yday", "MAIN", "NIFTYTESTY", "SHORT", DAY0 - 90000, 100.0)\nrepo.close_leg(y["id"], exit_ts=DAY0 - 1, exit_price=60.0, exit_reason="FLIP")\nt_main = leg("g_today", "MAIN", "NIFTYTESTT", "SHORT", DAY0 - 90000, 120.0)\nt_wing = leg("g_today", "WING", WSYM, "LONG", DAY0 - 90000, 8.0, leg_action="BUY")\nrepo.close_leg(t_main["id"], exit_ts=DAY0 + 1, exit_price=100.0, exit_reason="SIGNAL_EXIT")\nrepo.close_leg(t_wing["id"], exit_ts=DAY0 + 1, exit_price=5.0, exit_reason="SIGNAL_EXIT")\nimport sqlite3\nwith sqlite3.connect(repo.db_path) as c:                    # independent of close_leg\'s own pnl math\n    c.execute("UPDATE vet_trades SET pnl=26000, charges=400, net_pnl=25600 WHERE id=?", (y["id"],))\n    c.execute("UPDATE vet_trades SET pnl=13000, charges=300, net_pnl=12700 WHERE id=?", (t_main["id"],))\n    c.execute("UPDATE vet_trades SET pnl=-1950, charges=100, net_pnl=-2050 WHERE id=?", (t_wing["id"],))\ns = R.vet_state()\nby = {g["group_id"]: g for g in s["closed"]}\ncheck("both closed groups listed, open one excluded", set(by) == {"g_yday", "g_today"})\ncheck("exit 1s BEFORE IST midnight is not today", by["g_yday"]["today"] is False)\ncheck("exit 1s AFTER IST midnight is today (entered yesterday)", by["g_today"]["today"] is True)\ncheck("wing folded into the position net", by["g_today"]["net"] == 10650.0 and by["g_today"]["has_wing"])\ncheck("today_net counts today\'s exits only", s["today_net"] == 10650.0, str(s["today_net"]))\ncheck("closed_today counts positions, not legs", s["day"]["closed_today"] == 1)\ncheck("standard licence: reasons masked", all(g["reason"] == "CLOSED" for g in s["closed"]))\nset_admin(True)\ncheck("admin: real reasons", {g["reason"] for g in R.vet_state()["closed"]} == {"FLIP", "SIGNAL_EXIT"})\n\nprint("── 6. flat + frozen engine")\nmgr.pos = None\nwith sqlite3.connect(repo.db_path) as c:\n    c.execute("UPDATE vet_trades SET status=\'CLOSED\', exit_ts=?, exit_price=90, net_pnl=1 WHERE id=?", (NOW, main["id"]))\ns = R.vet_state()\ncheck("manager up + flat -> no DB fallback, position None", s["position"] is None and s["position_source"] is None)\nFakeEng.status = lambda self: {"frozen": True, "freeze_reason": "prefix guard", "warmup_ok": True}\ns = R.vet_state()\ncheck("engine freeze surfaces with its reason", s["frozen"] and s["freeze_reason"] == "prefix guard")\n\nprint("── 7. v1 endpoints untouched")\ncheck("/status still answers", "manager" in R.vet_status())\ncheck("/trades still answers", "trades" in R.vet_trades_route(limit=10, status="all"))\n\nlicense_state.ui_level = _real_level\nL._manager = None; L._engine = None\nprint()\nif FAILS:\n    print(f"  {len(FAILS)} FAILED: {FAILS}")\n    sys.exit(1)\nprint("  ALL CHECKS PASSED")\n'


def fail(msg):
    print(f"  ABORT  {msg}")
    sys.exit(1)


def both_trees(rel, single):
    out = [os.path.join(ROOT, rel)]
    if rel.startswith("backend/") and not single:
        out.append(os.path.join(DESKTOP_BACKEND, rel[len("backend/"):]))
    return out


def read(p):
    with open(p, encoding="utf-8") as f:
        return f.read()


def git_dirty(rels):
    """Working-copy drift scar (ORB_RECONCILE): an 'M' is a stop sign."""
    try:
        r = subprocess.run(["git", "status", "--porcelain", "--"] + rels,
                           cwd=ROOT, capture_output=True, text=True, timeout=20)
        if r.returncode != 0:
            return None
        return [ln for ln in r.stdout.splitlines() if ln.strip()]
    except Exception:
        return None


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--check", action="store_true", help="dry run, write nothing")
    ap.add_argument("--single-tree", action="store_true", help="CI checkout without desktop/src-tauri/backend")
    ap.add_argument("--allow-dirty", action="store_true", help="proceed although git shows local edits on the targets")
    ap.add_argument("--skip-tests", action="store_true")
    a = ap.parse_args()

    if not os.path.isdir(os.path.join(ROOT, "backend", "app")):
        fail("run this from the scalp-app repo root")
    if not a.single_tree and not os.path.isdir(DESKTOP_BACKEND):
        fail("desktop/src-tauri/backend missing — dual-tree is a hard requirement "
             "locally; pass --single-tree only on a CI checkout")

    # ── idempotency + prerequisites ──
    route_src = os.path.join(ROOT, ROUTE)
    panel_src = os.path.join(ROOT, PANEL)
    for p in (route_src, panel_src):
        if not os.path.exists(p):
            fail(f"{p} not found — VET_V1 integration missing, pull main first")
    rtext, ptext = read(route_src), read(panel_src)
    if FENCE in rtext and FENCE in ptext:
        print("  SKIP   VET panel v2 already present — nothing to do")
        return
    if FENCE in rtext or FENCE in ptext:
        fail("fence present in ONE of route/panel — mixed state, resolve by hand "
             f"(restore from .bak-{FENCE})")
    for needle in ('router = APIRouter(prefix="/api/vet"', "def vet_status():",
                   "def vet_trades_route(", "def _repo():"):
        if rtext.count(needle) != 1:
            fail(f"{ROUTE}: prerequisite {needle!r} x{rtext.count(needle)}, expected x1")
    if "def vet_state(" in rtext or '"/state"' in rtext:
        fail(f"{ROUTE} already defines /state from another patch — reconcile first")
    if "VET_V1 dashboard panel" not in ptext:
        fail(f"{PANEL} is not the v1 panel this script replaces — inspect it first")
    for rel in ("backend/app/engine/vet/vet_selection_loop.py",
                "backend/app/marketdata/ltp_store.py", "backend/app/license/license_state.py",
                "frontend/src/hooks/useEntitlements.js"):
        if not os.path.exists(os.path.join(ROOT, rel)):
            fail(f"prerequisite file missing: {rel}")
    if "def get_with_timestamp" not in read(os.path.join(ROOT, "backend/app/marketdata/ltp_store.py")):
        fail("LTPStore.get_with_timestamp missing — the freshness ladder depends on it")
    if "export const alpha" not in read(os.path.join(ROOT, "frontend/src/tokens.js")):
        fail("tokens.js has no alpha() — THEME_PHASE1 not applied?")

    dirty = git_dirty([ROUTE, PANEL])
    if dirty is None:
        print("  WARN   git status unavailable — cannot check for uncommitted drift")
    elif dirty and not a.allow_dirty:
        fail("uncommitted local edits on the targets (another session's patch?):\n         "
             + "\n         ".join(dirty) + "\n         commit/inspect first, or re-run with --allow-dirty")
    else:
        print("  OK     targets clean in git")

    # ── stage everything in memory ──
    new_route = rtext + ROUTE_BLOCK
    staged = {}
    for p in both_trees(ROUTE, a.single_tree):
        if not os.path.exists(p):
            fail(f"dual-tree copy missing: {p}")
        if read(p) != rtext:
            fail(f"dual-tree drift: {p} differs from {ROUTE} — sync the trees first")
        staged[p] = new_route
    for p in both_trees(TEST, a.single_tree):
        staged[p] = TEST_BODY
    staged[panel_src] = PANEL_BODY
    # append-only proof: everything above the fence is byte-identical
    if not new_route.startswith(rtext):
        fail("internal: route edit is not append-only")
    print(f"  OK     prerequisites verified ({len(staged)} file writes staged)")

    # ── compile gates on the staged text ──
    tmp = tempfile.mkdtemp(prefix="vetp_gate_")
    jsx = []
    for i, (p, body) in enumerate(staged.items()):
        t = os.path.join(tmp, f"{i}_{os.path.basename(p)}")
        with open(t, "w", encoding="utf-8") as f:
            f.write(body)
        if p.endswith(".py"):
            try:
                py_compile.compile(t, doraise=True)
            except py_compile.PyCompileError as e:
                fail(f"py_compile gate: {p}: {e}")
        else:
            jsx.append((p, t))
    print("  OK     py_compile gate passed")
    esb, npx = shutil.which("esbuild"), shutil.which("npx")
    for p, t in jsx:
        cmd = ([esb] if esb else [npx, "--yes", "esbuild"] if npx else None)
        if cmd is None:
            print(f"  WARN   esbuild unavailable — JSX gate skipped for {p}")
            continue
        r = subprocess.run(cmd + ["--loader:.jsx=jsx", t, "--outfile=" + os.devnull],
                           capture_output=True, text=True, cwd=os.path.join(ROOT, "frontend"))
        if r.returncode != 0:
            fail(f"esbuild gate: {p}:\n{r.stderr[-2000:]}")
        print("  OK     esbuild JSX gate passed")

    if a.check:
        for p in sorted(staged):
            print(f"  WOULD  {'edit ' if os.path.exists(p) else 'create'} {p}")
        print("  CHECK  dry run complete — no files written")
        return

    # ── write (backups only now, never during --check) ──
    created, backed = [], []
    for p, body in sorted(staged.items()):
        os.makedirs(os.path.dirname(p), exist_ok=True)
        if os.path.exists(p):
            shutil.copy2(p, p + f".bak-{FENCE}")
            backed.append(p)
        else:
            created.append(p)
        with open(p, "w", encoding="utf-8") as f:
            f.write(body)
        print(f"  WROTE  {p}")

    def rollback(why):
        for p in backed:
            shutil.copy2(p + f".bak-{FENCE}", p)
        for p in created:
            try:
                os.remove(p)
            except OSError:
                pass
        fail(f"{why} — ALL files restored to their pre-patch state")

    # ── grep-count verification ──
    for rel, needle, n in ((ROUTE, FENCE, 2), (ROUTE, "def vet_status():", 1),
                           (ROUTE, '@router.get("/state")', 1), (PANEL, FENCE, 1),
                           (TEST, FENCE, 1)):
        got = read(os.path.join(ROOT, rel)).count(needle)
        print(f"  {'OK ' if got >= n else 'BAD'}    {rel}: {needle!r} x{got} (need >= {n})")
        if got < n:
            rollback("verification failed")

    # ── behavioural suite (real clock) ──
    if a.skip_tests:
        print("  WARN   --skip-tests: behavioural suite NOT run")
    else:
        env = dict(os.environ, PYTHONPATH=os.path.join(ROOT, "backend"))
        r = subprocess.run([sys.executable, os.path.join(ROOT, TEST)], cwd=os.path.join(ROOT, "backend"),
                           env=env, capture_output=True, text=True, timeout=300)
        tail = "\n".join(ln for ln in r.stdout.splitlines() if "FAIL" in ln or "CHECKS" in ln or "FAILED" in ln)
        if r.returncode != 0 or "ALL CHECKS PASSED" not in r.stdout:
            print(r.stdout[-3000:]); print(r.stderr[-2000:])
            rollback("behavioural suite failed")
        print(f"  OK     behavioural suite: {r.stdout.count('  PASS  ')} checks — {tail.strip()}")

    ist = datetime.now(timezone(timedelta(hours=5, minutes=30)))
    in_session = ist.weekday() < 5 and (9, 0) <= (ist.hour, ist.minute) <= (15, 30)
    print()
    print("  DONE   VET dashboard v2 applied (files only — nothing was restarted).")
    if in_session:
        print("  NOTE   market session is open and the fleet has a LIVE strategy:")
        print("         rebuild + restart AFTER 15:30 IST (no-live-deploy rule).")
    print("  NEXT   ./desktop/build-scalp.sh both   → restart → Dashboard → Velvet")
    print("         curl -s localhost:<port>/api/vet/state | python3 -m json.tool")
    print(f"         then commit the three files (fence {FENCE}); keep *.bak-* out of git")


if __name__ == "__main__":
    main()
